def find_nth_digit(numerator, denominator, n):
    # Ensure the fraction is in its simplest form
    from math import gcd
    common_divisor = gcd(numerator, denominator)
    numerator //= common_divisor
    denominator //= common_divisor

    # Handle the case where the fraction is an integer
    if numerator % denominator == 0:
        return str(numerator)[n-1] if n <= len(str(numerator)) else '0'

    # Find the repeating part of the decimal expansion
    remainder = numerator % denominator
    seen_remainders = {}
    repeating_start = -1

    for i in range(1, n + 1):
        if remainder in seen_remainders:
            repeating_start = seen_remainders[remainder]
            break
        seen_remainders[remainder] = i
        remainder *= 10
        digit = remainder // denominator
        remainder %= denominator

    if repeating_start == -1:
        # No repeating part, return the nth digit directly
        return str(digit)
    else:
        # There is a repeating part
        non_repeating_length = repeating_start
        repeating_length = i - repeating_start

        if n <= non_repeating_length:
            # The nth digit is in the non-repeating part
            return str(digit)
        else:
            # The nth digit is in the repeating part
            n -= non_repeating_length
            return str((numerator * 10 ** (n - 1) // denominator) % 10)

